/* crosswalk cards, r24. */
(window.LADDER_CARDS=window.LADDER_CARDS||{})["24a"]=[{"q": "y′ = x − y² ties y to its slope. What is it called on this page?", "a": "a rate statement", "w": ["a start", "a solution", "an area form"], "why": "A rate statement is an equation tying an unknown function to its slopes."}, {"q": "y″ = −y. What is its order?", "a": "second", "w": ["first", "zero", "minus one"], "why": "The order is the highest slope in the statement."}, {"q": "y = Ceˣ − x − 1 and the statement y′ = x + y. Is y a solution, and where?", "a": "yes, for every C, on the whole line", "w": ["only for C = 0", "only at x = 0", "no, at no x"], "why": "y′ = Ceˣ − 1, and x + y = Ceˣ − 1 at every x."}, {"q": "y = x² makes y′ = x + y true at x = 0 and x = 1. Is it a solution?", "a": "no: the statement must hold on an open interval", "w": ["yes, on [0, 1]", "yes, at those two points", "yes, since it holds somewhere"], "why": "A solution makes the equation true at every x of an open interval."}, {"q": "y′ = −xy with y(0) = 3. What is the pair (0, 3) called?", "a": "the start", "w": ["the order", "the rate statement", "the solution"], "why": "A start fixes y(x₀) = y₀; with the statement it makes one question."}, {"q": "A culture grows at 0.3 of itself per hour from 2000 cells. Which function is its count?", "a": "2000e^(0.3x)", "w": ["2000 + 0.3x", "2000(0.3)ˣ", "2000e^(x/0.3)"], "why": "The own-rate technique: y′ = ky from (0, A) gives Ae^(kx)."}, {"q": "z′ = kz and g = z·e^(−kx). What is g′?", "a": "0", "w": ["kz", "z", "−kz"], "why": "The product technique gives (kz − kz)e^(−kx)."}, {"q": "g′ = 0 on an interval, so g is constant. What licenses that line?", "a": "zero slope means flat (14d)", "w": ["the product technique", "the chain technique", "the own-rate technique"], "why": "A function with slope 0 on an interval is constant there."}, {"q": "y′ = y, so y′/y = 1, so ln y = x + C. What is lost?", "a": "y = 0 and the negative solutions", "w": ["nothing", "only the start", "the positive solutions"], "why": "Dividing by y needs y ≠ 0; ln y needs y > 0."}, {"q": "y′ = ky, y(0) = A, so y = A + kAx. What has been found?", "a": "the tangent line at the start", "w": ["the solution", "the area form", "the growth function"], "why": "1 + x matches eˣ at the start and its slope there, nothing more."}, {"q": "Some functions of one form solve a statement. Does every solution have that form?", "a": "not until it is proved", "w": ["yes, always", "yes, if the start fits", "no, never"], "why": "Checking some solutions says nothing about the others."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["24b"]=[{"q": "y(x) = y₀ + ∫ₓ₀ˣ F(t, y(t)) dt. What is it called on this page?", "a": "the area form", "w": ["the start", "the largest gap", "the tangent line"], "why": "The statement and its start written as one statement about areas."}, {"q": "y obeys the area form. What licenses y′ = F(x, y)?", "a": "the slope of an area is the height (16b)", "w": ["evaluating by antiderivatives (16c)", "the own-rate technique", "zero slope means flat (14d)"], "why": "Differentiating the area function gives the height F(x, y(x))."}, {"q": "In the area form, what is y(x₀)?", "a": "y₀", "w": ["0", "F(x₀, y₀)", "y′(x₀)"], "why": "An area from x₀ to x₀ is 0."}, {"q": "y₀ = 1, yₙ₊₁ = 1 + ∫₀ˣ yₙ. What is yₙ?", "a": "the matching polynomial Tₙ of eˣ", "w": ["eˣ itself", "xⁿ/n!", "1 + nx"], "why": "Each round integrates term by term and adds one more piece."}, {"q": "yₙ₊₁(x) = y₀ + ∫ₓ₀ˣ F(t, yₙ(t)) dt. What is this list of guesses called?", "a": "repeated integration", "w": ["the shrinking map", "the drift bound", "the tangent line"], "why": "Feed a guess into the statement, take the area, add the start."}, {"q": "y′ = 2xy, y(0) = 1. What is y₁?", "a": "1 + x²", "w": ["1 + 2x", "x²", "1 + x"], "why": "y₁ = 1 + ∫₀ˣ 2t dt."}, {"q": "A round reads yₙ₊₁ = ∫ₓ₀ˣ F(t, yₙ(t)) dt. What is wrong?", "a": "the start y₀ is missing", "w": ["the last guess is fed in", "nothing", "the area should be from 0"], "why": "Without y₀ the guesses solve the statement with start 0."}, {"q": "A round feeds yₙ₊₁ into its own area. What is wrong?", "a": "it is not a recipe: yₙ₊₁ is on both sides", "w": ["the start is missing", "nothing", "it settles too slowly"], "why": "A round must feed in the guess already built."}, {"q": "The guesses settle at each point only. May the areas pass to the limit?", "a": "not yet: that needs settling everywhere at once", "w": ["yes, always", "yes, if the limit is continuous", "no, never"], "why": "The area-at-once technique (23e1) asks for settling everywhere at once."}, {"q": "Gaps between guesses are at most rⁿ⁺¹/(n + 1)! on [−r, r]. What follows?", "a": "the guesses settle everywhere at once", "w": ["the guesses wander", "they settle only at 0", "nothing"], "why": "The sum of the ceilings settles, so the at-once comparison technique applies."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["24c"]=[{"q": "The largest value of |f(x) − g(x)| on [u, v]. What is it called on this page?", "a": "the largest gap ‖f − g‖", "w": ["the area between", "the drift bound", "the reach"], "why": "It measures how far apart two functions are."}, {"q": "Why does ‖f − g‖ exist for continuous f, g on [u, v]?", "a": "|f − g| is continuous, so it has a highest value (12c)", "w": ["every function has a largest value", "f and g are bounded by 1", "by the triangle technique"], "why": "The highest-and-lowest technique needs continuity on a closed interval."}, {"q": "f(x) = x², g(x) = x on [0, 2]. What is ‖f − g‖?", "a": "2", "w": ["¼", "4", "0"], "why": "|x² − x| is ¼ at x = ½ but 2 at x = 2."}, {"q": "‖f − h‖ ≤ ‖f − g‖ + ‖g − h‖. What licenses it?", "a": "the triangle technique (8h), at each x", "w": ["the shrinking-map technique", "the mean value technique", "the crowd technique alone"], "why": "Bound the gap at each x, then take the largest."}, {"q": "fₙ settles everywhere at once to f. What does ‖fₙ − f‖ do?", "a": "heads to 0", "w": ["stays fixed", "heads to 1", "passes every ceiling"], "why": "Settling everywhere at once is settling in the largest gap."}, {"q": "Continuous fₙ crowd in the largest gap. What follows?", "a": "they settle everywhere at once to a continuous f", "w": ["they settle only at each point", "they may wander", "their limit may break"], "why": "The function-crowd technique."}, {"q": "xⁿ on [0, 1]: is ‖xⁿ − x²ⁿ‖ small for large n?", "a": "no: it is ¼ for every n", "w": ["yes: it heads to 0", "yes: it is 1/n", "no: it is 1"], "why": "With u = xⁿ, the gap u − u² peaks at ¼."}, {"q": "‖Tf − Tg‖ ≤ ½‖f − g‖ for all f, g in D. What is T?", "a": "a map that shrinks", "w": ["a tame statement", "a largest gap", "a start"], "why": "One fixed k < 1 for every pair."}, {"q": "g(x) = √(x² + 1) pulls every two points closer. Why no fixed point?", "a": "no single k < 1 works", "w": ["it is not continuous", "it rises", "its slope is 0"], "why": "The ratio of gaps comes as close to 1 as you like."}, {"q": "x ↦ x/2 on (0, 1] shrinks. Why no fixed point?", "a": "the set does not keep its limits", "w": ["k is too large", "it does not shrink", "it is not continuous"], "why": "The run heads to 0, which is outside (0, 1]."}, {"q": "After n rounds, how close is Tⁿf₀ to the fixed function?", "a": "within kⁿ/(1 − k) times the first step", "w": ["within k times the first step", "within kⁿ", "exactly there"], "why": "Add the shrinking steps as a geometric sum."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["24d"]=[{"q": "|F(x, y) − F(x, z)| ≤ L|y − z| on R. What is F called on this page?", "a": "tame", "w": ["shrinking", "continuous only", "a start"], "why": "The slope changes no faster than in proportion to a change of place."}, {"q": "F = |y| on [−1, 1] × [−1, 1]. Is it tame?", "a": "yes, with L = 1", "w": ["no: no slope at 0", "no: not continuous", "yes, with L = 0"], "why": "||y| − |z|| ≤ |y − z|; a slope ceiling is enough, not needed."}, {"q": "F = y^(1/3) near y = 0. Is it tame?", "a": "no", "w": ["yes, with L = 1", "yes, with L = 3", "yes, since it is continuous"], "why": "y^(1/3)/y = y^(−2/3) passes every ceiling."}, {"q": "|∂_y F| ≤ L on R, so F is tame there. What licenses it?", "a": "the mean value technique (14c)", "w": ["the triangle technique", "the drift technique", "the area form"], "why": "F(x, y) − F(x, z) is a slope in y times y − z."}, {"q": "y′ = x² + y², y(0) = 0, α = β = 1. What are M and L?", "a": "M = 2, L = 2", "w": ["M = 1, L = 2", "M = 2, L = 1", "M = 4, L = 4"], "why": "x² + y² ≤ 2 on the square; the slope in y is 2y."}, {"q": "h ≤ α, hM ≤ β, hL < 1. What does the existence technique then give?", "a": "exactly one solution on [x₀ − h, x₀ + h]", "w": ["a solution on the whole line", "at least two solutions", "one solution on [x₀, x₀ + α]"], "why": "Repeated integration shrinks on that stretch."}, {"q": "|(Ty)(x) − y₀| ≤ hM ≤ b. What does that line show?", "a": "T sends D into D", "w": ["T shrinks", "the solution is unique", "F is tame"], "why": "The guesses stay in the rectangle."}, {"q": "‖Ty − Tz‖ ≤ hL‖y − z‖. What makes T shrink?", "a": "hL < 1", "w": ["hM ≤ b", "h ≤ a", "L > 1"], "why": "The shrink factor is k = hL."}, {"q": "Two solutions of a tame statement start 0.001 apart. What does the drift technique bound?", "a": "their gap by 0.001·e^(L|x − x₀|)", "w": ["their gap by 0.001", "their gap by L|x − x₀|", "nothing"], "why": "The drift technique: gaps grow at most like a growth function."}, {"q": "y′ = −2y, starts 1 and 1.001, x = 3. Is the drift bound sharp?", "a": "no: the true gap is far smaller", "w": ["yes, exactly", "no: the true gap is larger", "it gives no bound"], "why": "The bound uses the size of L, not its sign."}, {"q": "F continuous, so one solution from each start?", "a": "no: √|y| has many from 0", "w": ["yes, always", "yes, near the start", "no, never"], "why": "Continuity is not tameness."}, {"q": "hL < 1 holds only for h < ½. Does the solution stop at ½?", "a": "not necessarily: the condition is the proof's", "w": ["yes, always", "yes, if F is tame", "it stops at h exactly"], "why": "y′ = y has h ≤ ½ on the unit square, yet eˣ lasts forever."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["24e"]=[{"q": "y′ = √|y|, y(0) = 0. How many solutions?", "a": "endlessly many", "w": ["one", "two", "none"], "why": "Wait until any c ≥ 0, then rise as (x − c)²/4."}, {"q": "y = 0 for x ≤ c, (x − c)²/4 after. Which statement does it solve?", "a": "y′ = √|y|", "w": ["y′ = y²", "y′ = y", "y′ = 2√|y|"], "why": "For x > c the slope is (x − c)/2 = √y."}, {"q": "Why does 24d not fix the future of y′ = √|y| from 0?", "a": "√|y| is not tame near 0", "w": ["√|y| is not continuous", "the start is not allowed", "hM > b"], "why": "1/√y passes every ceiling as y heads to 0."}, {"q": "y′ = 3y^(2/3), y(0) = 0. Is y = x³ a solution?", "a": "yes, and so is y = 0", "w": ["yes, the only one", "no", "only for x ≥ 0"], "why": "(x³)′ = 3x² = 3(x³)^(2/3)."}, {"q": "y′ = y², y(0) = 1. What is the solution?", "a": "1/(1 − x), for x < 1", "w": ["eˣ", "1/(1 + x), for x > −1", "1 + x"], "why": "Its slope is 1/(1 − x)², which is y²."}, {"q": "y′ = y² from (0, 1) passes every ceiling as x heads to 1. What is this called on this page?", "a": "running off", "w": ["many futures", "drifting apart", "shrinking"], "why": "The run-off technique."}, {"q": "y′ = y² is tame on every bounded rectangle. Does its solution last forever?", "a": "no: it leaves every bounded rectangle", "w": ["yes, by 24d", "yes, if L is small", "no: it is not tame"], "why": "Tame on bounded rectangles only; L = 2B grows with B."}, {"q": "y′ = y², y(0) = −1. Going forward, does it run off?", "a": "no: it rises toward 0 and stays bounded", "w": ["yes, at x = 1", "yes, at x = −1", "it stops at 0"], "why": "y = −1/(1 + x) exists for every x > −1."}, {"q": "1/(1 − x) at x = 2 is −1. Is that the same solution as from (0, 1)?", "a": "no: it solves from another start", "w": ["yes, continued through 1", "yes, by uniqueness", "no: it solves no statement"], "why": "No solution from (0, 1) reaches x = 1."}, {"q": "Tangent-line steps for y′ = y² give 19.7 at x = 1.2. What does that show?", "a": "steps can report values where no solution exists", "w": ["the solution is 19.7 there", "the statement is not tame", "the steps are exact"], "why": "Stepping never notices the run-off at x = 1."}, {"q": "A tame statement fixes the future. For how long?", "a": "while the solution stays in bounds", "w": ["forever", "only for h", "until x = 1"], "why": "A tame statement's solution can still run off."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["24f"]=[{"q": "y′ = x·y². Does the statement part into an input piece times a height piece?", "a": "yes: g(x) = x, h(y) = y²", "w": ["no: y² holds the height twice", "yes: g(x) = y², h(y) = x", "only when y > 0"], "why": "The slope is a function of x alone times a function of y alone."}, {"q": "y′ = x + y. Does the statement part?", "a": "no", "w": ["yes: g(x) = x, h(y) = y", "yes, after dividing by y", "yes: g(x) = 1, h(y) = x + y"], "why": "A sum of an input piece and a height piece is not their product; 24g solves it."}, {"q": "y′ = g(x)h(y), y(x₀) = y₀, h ≠ 0 between the heights. What do the two areas satisfy?", "a": "∫ from y₀ to y of ds/h(s) = ∫ from x₀ to x of g(t) dt", "w": ["∫ h(s) ds = ∫ g(t) dt", "∫ ds/h(s) = ∫ dt/g(t)", "∫ g(t) dt = y − y₀"], "why": "The side-by-side technique: the height piece is divided across before taking areas."}, {"q": "y′ = y cos x, y(0) = 2. What is the solution?", "a": "y = 2e^(sin x)", "w": ["y = 2e^(cos x)", "y = 2 + sin x", "y = e^(2 sin x)"], "why": "ln(y/2) = sin x, by the side-by-side technique."}, {"q": "A formula is put into the statement and the start, and both hold on an interval. Which technique makes it the only solution, when the statement is tame?", "a": "the put-back technique", "w": ["the side-by-side technique", "the resting-line technique", "the own-rate technique"], "why": "Putting back shows it is a solution; the drift technique, with equal starts, shows no other."}, {"q": "y′ = y(1 − y). Which flat lines solve it?", "a": "y = 0 and y = 1", "w": ["y = 1 only", "y = 0 only", "none: flat lines have slope 0"], "why": "A flat line y = c solves it exactly when h(c) = 0."}, {"q": "y′ = y², and the answer is written y = −1/(x + C). Which solution has no C?", "a": "y = 0", "w": ["y = 1", "y = −1", "y = 1/(1 − x)"], "why": "Dividing by y² lost the resting line y = 0."}, {"q": "A tame statement parts, h(1) = 0, and a solution has y(0) = 3. Can it ever reach the height 1?", "a": "no", "w": ["yes, at some x past 0", "yes, as x heads past every bound", "only if g changes sign"], "why": "The resting-line technique: two solutions through one point would have to agree."}, {"q": "h′ = −0.2√h for a draining tank. Why can solutions reach the resting line h = 0?", "a": "√h is not tame near 0", "w": ["√h is not continuous at 0", "the statement does not part", "the tank's statement runs off"], "why": "√h/h = 1/√h passes every ceiling, so the resting-line technique does not apply."}, {"q": "dy/y = dx, so ln y = x + C. What is wrong with that line?", "a": "the area under 1/y is ln|y|", "w": ["the area under 1/y is 1/y²", "dx has no area", "C must be 0"], "why": "ln y needs y > 0; negative solutions and y = 0 are lost."}, {"q": "y = 2/(2 − x²) solves y′ = xy², y(0) = 1. On which interval does the solution from (0, 1) live?", "a": "−√2 < x < √2", "w": ["every x except ±√2", "x > −√2", "the whole line"], "why": "A solution lives on one interval holding its start; it runs off at ±√2."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["24g"]=[{"q": "Which statement is straight in y?", "a": "y′ + x²y = sin x", "w": ["y′ + y² = x", "y′ = √y + x", "y′ = xy²"], "why": "y appears once, times a function of x alone."}, {"q": "y′ + p(x)y = q(x). What is the multiplying factor?", "a": "e^(P), with P an antiderivative of p", "w": ["e^(p)", "e^(q)", "1/p"], "why": "Then (e^P y)′ = e^P(y′ + py)."}, {"q": "y′ + 2xy = x. What is the factor?", "a": "e^(x²)", "w": ["e^(2x)", "e^(x)", "x²"], "why": "An antiderivative of 2x is x²."}, {"q": "After multiplying y′ + 3y = 6 by e^(3x), what does the left side become?", "a": "(e^(3x)y)′", "w": ["(3e^(3x)y)′", "e^(3x)y′", "(e^(3x) + y)′"], "why": "The product technique: (e^(3x)y)′ = e^(3x)y′ + 3e^(3x)y."}, {"q": "(e^(3x)y)′ = 6e^(3x), y(0) = 0. What is y?", "a": "2 − 2e^(−3x)", "w": ["2", "2e^(3x) − 2", "6 − 6e^(−3x)"], "why": "e^(3x)y = 2e^(3x) − 2; divide by e^(3x)."}, {"q": "What is the accepted name of the multiplying factor e^P?", "a": "the integrating factor", "w": ["the growth factor", "the resting factor", "the trial factor"], "why": "The page gives it in the multiplying-factor technique."}, {"q": "xy′ + 2y = x², y(1) = 1. On which interval does the solution live?", "a": "x > 0", "w": ["the whole line", "x ≠ 0", "x > 1"], "why": "Dividing by x gives p = 2/x, continuous on (0, ∞), which holds the start."}, {"q": "A straight statement has p and q continuous on all of J. Can its solution run off inside J?", "a": "no", "w": ["yes, like y′ = y²", "only if q grows fast", "only for a negative start"], "why": "The whole-stretch technique: the formula is continuous, so bounded on every closed piece."}, {"q": "yₚ solves y′ + py = q. What are all the solutions?", "a": "yₚ + Ce^(−P), one for each C", "w": ["yₚ + C", "Cyₚ", "yₚ + Ce^(P)"], "why": "The one-plus-bare technique: the difference of two solutions solves the bare statement."}, {"q": "y′ + y = sin x. What happens to Ce^(−x) as x grows?", "a": "it fades, and every solution settles into one swing", "w": ["it grows, and the solutions part", "it stays the same size", "it swings with sin x"], "why": "The bare part is Ce^(−x), which heads to 0."}, {"q": "y′ + 2y = x is multiplied by e^(2x), and the next line reads (e^(2x)y)′ = x. What went wrong?", "a": "the push was not multiplied too", "w": ["the factor should be e^(x²)", "the product technique fails here", "the start was not used"], "why": "(e^(2x)y)′ = xe^(2x)."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["24h"]=[{"q": "y′ = k(y − A), y(x₀) = y₀. What is the solution?", "a": "A + (y₀ − A)e^(k(x − x₀))", "w": ["y₀e^(k(x − x₀)) − A", "A + y₀e^(kx)", "(y₀ − A)e^(k(x − x₀))"], "why": "The shift-to-rest technique: z = y − A grows at its own rate."}, {"q": "y′ = −0.3(y − 15). What do the solutions do as x grows?", "a": "every one heads to 15", "w": ["every one leaves 15", "they swing about 15", "they head to 0"], "why": "k < 0: the resting value pulls."}, {"q": "How many numbers does a start for y″ = −9y need?", "a": "two: a height and a slope", "w": ["one: a height", "one: a slope", "three: a height and two slopes"], "why": "A second-order statement speaks of y″; cos 3x and cos 3x + sin 3x share a height at 0."}, {"q": "y″ = −n²y. Which quantity is flat along every solution?", "a": "y′² + n²y²", "w": ["y′ + ny", "y² − n²y′²", "y″ + y"], "why": "Its slope is 2y′(y″ + n²y) = 0."}, {"q": "y″ = −4y, y(0) = 0, y′(0) = 2. What is the solution?", "a": "sin 2x", "w": ["2 sin 2x", "sin x", "2 cos 2x"], "why": "The steady-swing technique: (B/n) sin nx with B = 2, n = 2."}, {"q": "What is the period of every solution of y″ = −25y?", "a": "2π/5", "w": ["2π/25", "5", "10π"], "why": "Every solution repeats every 2π/n, here n = 5."}, {"q": "y″ − 5y′ + 6y = 0. What is its trial equation?", "a": "r² − 5r + 6 = 0", "w": ["r² + 5r + 6 = 0", "r − 5 + 6 = 0", "e^(rx) = 0"], "why": "y = e^(rx) gives (r² − 5r + 6)e^(rx) = 0."}, {"q": "y″ − 5y′ + 6y = 0. What are all the solutions?", "a": "C₁e^(2x) + C₂e^(3x)", "w": ["C₁e^(−2x) + C₂e^(−3x)", "(C₁ + C₂x)e^(5x)", "C₁ cos 2x + C₂ sin 3x"], "why": "The trial equation has roots 2 and 3; the tried-growth technique."}, {"q": "y″ + 6y′ + 9y = 0. What are all the solutions?", "a": "(C₁ + C₂x)e^(−3x)", "w": ["C₁e^(−3x) + C₂e^(−3x)", "C₁e^(3x) + C₂e^(−3x)", "C₁ cos 3x + C₂ sin 3x"], "why": "r = −3 twice; the second solution is xe^(−3x)."}, {"q": "y″ + 2y′ + 5y = 0. What is the status of solving it from its trial equation?", "a": "held in trust, since the roots are not real", "w": ["no solution exists", "solved by the steady-swing technique", "solved by the tried-growth technique"], "why": "b² − 4c = −16 < 0; 26·cb24 pays it."}, {"q": "Which technique proves only one solution of y″ = −n²y with a given height and slope?", "a": "the steady-swing technique", "w": ["the drift technique", "the shift-to-rest technique", "the tried-growth technique"], "why": "Its proof uses the flat energy of the gap between two solutions, not 24d."}, {"q": "In the tried-growth technique, why put w = y′ − r₂y?", "a": "w obeys w′ = r₁w, a first-order statement", "w": ["w is always 0", "w is the energy of y", "w makes the statement part"], "why": "The statement splits into two first-order statements, each with one solution."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["24i"]=[{"q": "yₙ₊₁ = yₙ + h·F(xₙ, yₙ). What is this step called on the page?", "a": "a forward step", "w": ["a look-ahead step", "a backward step", "repeated integration"], "why": "It keeps the slope at the start of the step for the whole step."}, {"q": "y′ = ky from (0, A), n forward steps of length x/n. Where do they land?", "a": "A(1 + kx/n)ⁿ", "w": ["Ae^(kx)", "A(1 + kx)ⁿ", "A + kxn"], "why": "Each step multiplies by 1 + hk; the small-step technique."}, {"q": "A forward walk with step h. About how big is the slip of one step?", "a": "about h²", "w": ["about h", "about h³", "about 1/h"], "why": "The match-error technique with n = 1: the slip is a second slope times h²/2."}, {"q": "A forward walk to a fixed x. Halve h. What happens to the walk’s error, roughly?", "a": "it halves", "w": ["it falls to a quarter", "it stays the same", "it doubles"], "why": "Each slip is a quarter, but there are twice as many steps."}, {"q": "|yₙ − y(xₙ)| ≤ (Kh/2L)(e^(L(x − x₀)) − 1). Which technique gives the factor e^(L(x − x₀))?", "a": "the drift technique", "w": ["the own-rate technique", "the shrinking-map technique", "the area-form technique"], "why": "Each slip is a new start, and starts of a tame statement drift apart no faster than that."}, {"q": "ỹ = yₙ + h·F(xₙ, yₙ), then yₙ₊₁ = yₙ + (h/2)(F(xₙ, yₙ) + F(xₙ₊₁, ỹ)). What is this?", "a": "a look-ahead step", "w": ["a forward step", "a backward step", "a stiff step"], "why": "A trial step, then the average of the two slopes."}, {"q": "One look-ahead step on y′ = ky. What does it multiply y by?", "a": "1 + hk + (hk)²/2", "w": ["1 + hk", "1 + hk + (hk)²", "e^(hk)"], "why": "The matching polynomial of e^(hk) of degree 2."}, {"q": "The look-ahead walk on y′ = f(x), a statement with no y in it. Which sum is it?", "a": "the trapezoid sum", "w": ["the left-box sum", "the parabola sum", "the midpoint sum"], "why": "Each step adds h times the average of f at the two ends."}, {"q": "Forward steps on y′ = −30y with h = 0.1. Do they shrink toward 0?", "a": "no: they double in size and alternate", "w": ["yes, by a factor 0.7 a step", "yes, but slowly", "no: they stay at 1"], "why": "Each step multiplies by 1 − 3 = −2; steady needs hk < 2."}, {"q": "yₙ₊₁ = yₙ/(1 + hk) for y′ = −ky. Which step gives this?", "a": "a backward step", "w": ["a forward step", "a look-ahead step", "a midpoint step"], "why": "The new value’s slope is used, so solve yₙ₊₁ = yₙ − hk·yₙ₊₁."}, {"q": "A statement holds a part that dies fast beside a part that moves slowly. What is the statement called?", "a": "stiff", "w": ["tame", "not tame", "a run-off statement"], "why": "The fast part forces tiny forward steps long after it has died."}, {"q": "A walk rounds every value to two places and uses h = 0.001 on y′ = y from 1. What happens?", "a": "it never leaves 1", "w": ["it lands on e", "it lands near 2.5", "it runs off"], "why": "Each increment is under 0.005, so rounding erases it; smaller is not always better."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["24j"]=[{"q": "P′ = rP(1 − P/K). What are P = 0 and P = K for this statement?", "a": "resting lines", "w": ["ceilings", "run-off points", "starts"], "why": "The rate is 0 there, so each constant is a solution."}, {"q": "A solution starts at P₀ with 0 < P₀ < K. Which technique keeps it from ever touching K?", "a": "the resting-line technique", "w": ["the logistic-solution technique", "the fastest-growth technique", "the own-rate technique"], "why": "The statement is tame, and a solution that starts off a resting line never touches it."}, {"q": "Why does 17·bio’s use of ln P and ln(K − P) now hold for every t?", "a": "the solution stays strictly between 0 and K", "w": ["P is never negative by definition", "K is very large", "the statement is straight in P"], "why": "The stays-between technique: both logs have positive inputs."}, {"q": "P = K/(1 + Ce^(−rt)) with P₀ > K. What sign and size is C?", "a": "between −1 and 0", "w": ["above 0", "below −1", "exactly 0"], "why": "C = (K − P₀)/P₀ is negative and bigger than −1."}, {"q": "The logistic statement from a start below 0. What happens going forward?", "a": "it runs off to minus infinity at t = ln(−C)/r", "w": ["it climbs to K", "it rests at 0", "it falls to −K"], "why": "C < −1, so the bottom 1 + Ce^(−rt) reaches 0: the every-start technique."}, {"q": "u = 1/P for a logistic P. Which statement does u obey?", "a": "u′ = −r(u − 1/K)", "w": ["u′ = ru(1 − u/K)", "u′ = −ru²", "u′ = r(u − K)"], "why": "The reciprocal-cooling technique: u cools toward 1/K."}, {"q": "Counts at equal times give u = 1/P of 0.01, 0.004, 0.002. What is the factor q for the gap?", "a": "1/3", "w": ["2/5", "1/2", "1/4"], "why": "q = (u₃ − u₂)/(u₂ − u₁) = −0.002/−0.006."}, {"q": "For a logistic population, which gap shrinks by the same factor every year?", "a": "1/P − 1/K", "w": ["K − P", "P − P₀", "K/P − 1/K"], "why": "The reciprocal-cooling technique fixes the factor for the gap in 1/P, not in P."}, {"q": "Pₙ₊₁ = Pₙ + rPₙ(1 − Pₙ/K) with h = 1. What is the slope of the step at K?", "a": "1 − r", "w": ["−r", "1 + r", "r(1 − 2/K)"], "why": "g′(P) = 1 + r − 2rP/K, at P = K."}, {"q": "The yearly logistic walk with r = 2.5. Does it settle at K?", "a": "no: the slope at K is −1.5", "w": ["yes: the smooth statement settles", "yes: the slope at K is 0.5", "no: it runs off"], "why": "The logistic-walk technique: settling at K needs hr < 2."}, {"q": "The yearly walk, in x = hrP/((1 + hr)K). What map is it?", "a": "xₙ₊₁ = (1 + hr)xₙ(1 − xₙ)", "w": ["xₙ₊₁ = hr·xₙ(1 − xₙ)", "xₙ₊₁ = xₙ + hr(1 − xₙ)", "xₙ₊₁ = (1 − hr)xₙ"], "why": "Divide one step by c = (1 + hr)K/(hr)."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["24k"]=[{"q": "y′ = F(y), and F(y*) = 0. What is y*?", "a": "a resting place", "w": ["a cycle of two", "a doubling", "a bad point"], "why": "The rate is 0 there, so the constant y* is a solution."}, {"q": "F′(y*) < 0 at a resting place. What does it do?", "a": "it holds", "w": ["it falls apart", "nothing can be said", "it doubles"], "why": "The sign-of-slope technique: departures shrink like e^(−mt)."}, {"q": "y′ = y(y − 1)(y − 3). Which resting place holds?", "a": "1", "w": ["0", "3", "none of them"], "why": "F′(1) = 3 − 8 + 3 = −2 < 0; F′ is 3 at 0 and 6 at 3."}, {"q": "F′(y*) = 0 at a resting place. What does the sign-of-slope technique say?", "a": "nothing: it is silent", "w": ["it holds", "it falls apart", "it is a cycle"], "why": "y′ = −y³ holds at 0 and y′ = y³ falls apart there, both with slope 0."}, {"q": "y′ = μ − y² as a falls through 0. What happens to the resting places ±√μ?", "a": "they meet and vanish", "w": ["they swap which one holds", "two new ones appear beside 0", "they both start to hold"], "why": "The fold technique: none exist for a < 0."}, {"q": "y′ = μy − y³ with μ > 0. Which resting places hold?", "a": "±√μ", "w": ["0 only", "0 and ±√μ", "none"], "why": "The slope μ − 3y² is a at 0 and −2μ at ±√μ."}, {"q": "g(x) = μx(1 − x), fixed point 1 − 1/a. What is g′ there?", "a": "2 − μ", "w": ["μ − 1", "1 − μ", "μ(1 − μ)"], "why": "g′(x) = μ(1 − 2x) at x = 1 − 1/a."}, {"q": "g(p) = q and g(q) = p with p ≠ q. What are p and q?", "a": "a cycle of two", "w": ["two fixed points", "two resting places", "a doubling"], "why": "Each is left alone by g∘g but moved by g."}, {"q": "(g∘g)′(p) = g′(q)·g′(p). Which technique gives this line?", "a": "the chain technique", "w": ["the product technique", "the mean value technique", "the double technique"], "why": "The slope of g after g, at p, with g(p) = q."}, {"q": "g(x) = 4x(1 − x) and x₀ = sin²θ₀. What is xₙ?", "a": "sin²(2ⁿθ₀)", "w": ["sin²(nθ₀)", "4ⁿ sin²θ₀", "sin(2ⁿθ₀)"], "why": "4 sin²θ cos²θ = sin²2θ: each step doubles the angle."}, {"q": "At μ = 4, two starts 10⁻¹⁰ apart. About how many steps until their runs are unrelated?", "a": "about 33", "w": ["about 10", "about 4", "about 10¹⁰"], "why": "The angle gap doubles each step, and 2³³ ≈ 8.6 × 10⁹."}, {"q": "The doubling ratios approach about 4.669. What is that claim on this page?", "a": "a labelled guess, seen in many statements", "w": ["a technique proved here", "an axiom", "a law measured in a lab"], "why": "Computed doublings of several statements agree; no proof is given."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["24l"]=[{"q": "y = Σuₖxᵏ is put into a statement and each power is balanced. What does the statement become?", "a": "a recipe for the coefficients", "w": ["a resting place", "a starting-power equation", "an area form"], "why": "Each uₖ comes from the ones before."}, {"q": "Why must each power balance, not just the totals agree?", "a": "two sums with the same total near 0 have the same coefficients", "w": ["the reach is always 1", "the statement is tame", "every sum settles"], "why": "The smooth-sum technique: uₖ = f⁽ᵏ⁾(0)/k!."}, {"q": "y′ = 1 + 2xy, y(0) = 0. What is the recipe?", "a": "(k + 1)uₖ₊₁ = 2uₖ₋₁", "w": ["uₖ₊₁ = 2uₖ", "(k + 1)uₖ₊₁ = uₖ", "uₖ₊₂ = 2uₖ/(k + 2)"], "why": "Multiplying by 2x shifts each coefficient up one power."}, {"q": "A sum’s coefficients obey the recipe, and its reach is R > 0. Where does it solve the statement?", "a": "on |x − w| < R", "w": ["on the whole line", "only at x = w", "on |x − w| ≤ 2R"], "why": "The sum-solves technique works only inside the reach."}, {"q": "uₖ₊₂ = (k − n)(k + n + 1)uₖ/((k + 2)(k + 1)) with n = 2 and u₀ = 1. Which solution results?", "a": "1 − 3x²", "w": ["1 − x²", "1 + 3x²", "1 − 3x² + x⁴"], "why": "u₂ = −3, then u₄ = 0: the stopping-sum technique."}, {"q": "The sum of the other evenness for that statement, which never stops. What is its reach?", "a": "1", "w": ["no ceiling", "0", "2"], "why": "The ratio of neighbouring pieces heads to x²."}, {"q": "x²y″ + x·p(x)y′ + q(x)y = 0, and 1/x-type badness at 0. What is tried?", "a": "xˢ times a power sum", "w": ["a power sum alone", "e^(rx)", "a resting place"], "why": "The starting-power technique, at a bad point."}, {"q": "s(s − 1) + p(0)s + q(0) = 0. Where does this come from?", "a": "balancing the lowest power, xˢ", "w": ["balancing x⁰", "the reach of the sum", "the drift of two solutions"], "why": "Only u₀ reaches the lowest power, and u₀ ≠ 0."}, {"q": "4x²y″ + 4xy′ + (4x² − 1)y = 0. What are the starting powers?", "a": "½ and −½", "w": ["0 twice", "1 and −1", "2 and −1"], "why": "4s(s − 1) + 4s − 1 = 4s² − 1."}, {"q": "The drum’s statement x²y″ + xy′ + x²y = 0 has s² = 0. How many sums xˢΣuₖxᵏ does the technique give?", "a": "one", "w": ["two", "none", "endlessly many"], "why": "A double root gives one; the second solution needs ln x."}, {"q": "Σuₖxᵏ obeys the recipe, so it solves the statement at x = 2, though its reach is 1. Where does this break?", "a": "outside the reach the sum does not settle", "w": ["the recipe is wrong there", "the statement is not tame", "the start is wrong"], "why": "Pieces grow like x²ᵏ past the reach."}];
